  "application": "report-generation",
  "case_id": "case-education-student-performance-bangladesh-en",
  "language": "en",
  "report": {
    "type": "analytics-report",
    "audience": "education-policy-analysts and school administrators",
    "tone": "analytical, data-forward, actionable"
  },
  "brief": {
    "title": "Student Performance Analytics Report: Factors Influencing Academic Outcomes in Bangladesh",
    "one_liner": "A comprehensive analysis of academic, socio-economic, and environmental factors affecting student performance across districts in Bangladesh.",
    "goal": "Identify the key drivers of student academic success (SSC and HSC results), uncover disparities across demographic and socio-economic segments, and provide evidence-based recommendations for targeted educational interventions."
  },
  "required_sections": [
    {
      "section_id": "demographic-overview",
      "title": "Student Demographic Overview",
      "objective": "Summarize the composition of the student population by gender, age, district, and school type, providing context for subsequent analyses."
    },
    {
      "section_id": "academic-performance-analysis",
      "title": "Academic Performance Analysis",
      "objective": "Analyze the distribution and central tendencies of Previous GPA, SSC Result, and HSC Result, including performance classification (Excellent/Good/Average/Poor) and pass/fail rates."
    },
    {
      "section_id": "socioeconomic-impact",
      "title": "Socio-Economic Factors and Their Impact on Performance",
      "objective": "Examine how family income, parent education level, internet access, and private tuition correlate with student academic outcomes."
    },
    {
      "section_id": "study-behavior-attendance",
      "title": "Study Behavior and Attendance Patterns",
      "objective": "Investigate the relationship between study hours per week, attendance rates, and academic results to identify optimal study patterns."
    },
    {
      "section_id": "regional-disparities",
      "title": "Regional Performance Disparities",
      "objective": "Compare academic performance across districts and school types (public vs. private) to highlight geographic and institutional inequalities."
    },
    {
      "section_id": "recommendations",
      "title": "Key Findings and Policy Recommendations",
      "objective": "Synthesize insights into actionable recommendations for educators, administrators, and policymakers to improve student outcomes."
    }
  ],
  "kpis": [
    {
      "name": "Average HSC Result",
      "description": "Mean HSC GPA across all students, serving as the primary outcome metric (scale 0–5)."
    },
    {
      "name": "Excellent Performance Rate",
      "description": "Percentage of students achieving an HSC GPA of 4.5 or above, indicating top-tier academic achievement."
    },
    {
      "name": "At-Risk Student Rate",
      "description": "Percentage of students with an HSC GPA below 3.0, identifying those who may need additional support."
    },
    {
      "name": "GPA Progression Delta",
      "description": "Average difference between HSC Result and Previous GPA, indicating whether students are improving or declining over time."
    },
    {
      "name": "Attendance-Performance Correlation",
      "description": "Correlation coefficient between attendance percentage and HSC Result, quantifying the strength of attendance as a predictor."
    }
  ],
  "analysis_dimensions": [
    "Gender",
    "District",
    "School_Type",
    "Parent_Education",
    "Internet_Access"
  ]
}

