python3 << 'PYEOF'
import pandas as pd
import numpy as np

df = pd.read_csv('/app/benchmark/data.csv')

# KPIs
avg_hsc = df['HSC_Result'].mean()
excellent_rate = (df['HSC_Result'] >= 4.5).mean() * 100
at_risk_rate = (df['HSC_Result'] < 3.0).mean() * 100
gpa_delta = (df['HSC_Result'] - df['Previous_GPA']).mean()
attendance_corr = df['Attendance'].corr(df['HSC_Result'])
pass_rate = (df['HSC_Result'] >= 2.0).mean() * 100

# District stats
district_df = df.groupby('District').agg({
    'HSC_Result': ['mean', 'std', 'count'],
    'Study_Hours_per_Week': 'mean',
    'Attendance': 'mean',
    'Family_Income_BDT': 'mean',
    'Internet_Access': lambda x: (x == 'Yes').mean() * 100
}).round(4)
district_data = {}
for idx in district_df.index:
    district_data[idx] = {
        'avg_hsc': float(district_df.loc[idx, ('HSC_Result', 'mean')]),
        'std_hsc': float(district_df.loc[idx, ('HSC_Result', 'std')]),
        'count': int(district_df.loc[idx, ('HSC_Result', 'count')]),
        'avg_study_hours': float(district_df.loc[idx, ('Study_Hours_per_Week', 'mean')]),
        'avg_attendance': float(district_df.loc[idx, ('Attendance', 'mean')]),
        'avg_income': float(district_df.loc[idx, ('Family_Income_BDT', 'mean')]),
        'internet_pct': float(district_df.loc[idx, ('Internet_Access', '<lambda_0>')])
    }
district_data = dict(sorted(district_data.items(), key=lambda x: x[1]['avg_hsc'], reverse=True))

# Gender stats
gender_df = df.groupby('Gender').agg({
    'HSC_Result': ['mean', 'std', 'count'],
    'Previous_GPA': 'mean',
    'Attendance': 'mean'
}).round(4)
gender_data = {}
for idx in gender_df.index:
    gender_data[idx] = {
        'avg_hsc': float(gender_df.loc[idx, ('HSC_Result', 'mean')]),
        'std_hsc': float(gender_df.loc[idx, ('HSC_Result', 'std')]),
        'count': int(gender_df.loc[idx, ('HSC_Result', 'count')]),
        'avg_previous_gpa': float(gender_df.loc[idx, ('Previous_GPA', 'mean')]),
        'avg_attendance': float(gender_df.loc[idx, ('Attendance', 'mean')]),
        'gpa_delta': float(gender_df.loc[idx, ('HSC_Result', 'mean')] - gender_df.loc[idx, ('Previous_GPA', 'mean')])
    }

# School type stats
school_df = df.groupby('School_Type').agg({
    'HSC_Result': ['mean', 'std', 'count'],
    'Study_Hours_per_Week': 'mean',
    'Attendance': 'mean'
}).round(4)
school_data = {}
for idx in school_df.index:
    school_data[idx] = {
        'avg_hsc': float(school_df.loc[idx, ('HSC_Result', 'mean')]),
        'std_hsc': float(school_df.loc[idx, ('HSC_Result', 'std')]),
        'count': int(school_df.loc[idx, ('HSC_Result', 'count')])
    }

# Parent education stats
edu_df = df.groupby('Parent_Education').agg({
    'HSC_Result': ['mean', 'std', 'count'],
    'Family_Income_BDT': 'mean'
}).round(4)
edu_order = ['Primary', 'Secondary', 'Higher Secondary', 'Graduate']
edu_data = {}
for idx in edu_order:
    if idx in edu_df.index:
        edu_data[idx] = {
            'avg_hsc': float(edu_df.loc[idx, ('HSC_Result', 'mean')]),
            'std_hsc': float(edu_df.loc[idx, ('HSC_Result', 'std')]),
            'count': int(edu_df.loc[idx, ('HSC_Result', 'count')]),
            'avg_income': float(edu_df.loc[idx, ('Family_Income_BDT', 'mean')])
        }

# Internet access stats
inet_df = df.groupby('Internet_Access').agg({
    'HSC_Result': ['mean', 'std', 'count']
}).round(4)
inet_data = {}
for idx in inet_df.index:
    inet_data[idx] = {
        'avg_hsc': float(inet_df.loc[idx, ('HSC_Result', 'mean')]),
        'std_hsc': float(inet_df.loc[idx, ('HSC_Result', 'std')]),
        'count': int(inet_df.loc[idx, ('HSC_Result', 'count')])
    }

# Performance classification
def classify(gpa):
    if gpa >= 4.5: return 'Excellent'
    elif gpa >= 4.0: return 'Good'
    elif gpa >= 3.0: return 'Average'
    else: return 'Poor'
df['Performance_Class'] = df['HSC_Result'].apply(classify)
perf_dist = df['Performance_Class'].value_counts().to_dict()

# Income quartiles
df['Income_Quartile'] = pd.qcut(df['Family_Income_BDT'], q=4, labels=['Q1 (Lowest)', 'Q2', 'Q3', 'Q4 (Highest)'])
income_q = df.groupby('Income_Quartile', observed=True)['HSC_Result'].agg(['mean', 'count'])
income_data = {}
for idx in income_q.index:
    income_data[idx] = {
        'avg_hsc': float(income_q.loc[idx, 'mean']),
        'count': int(income_q.loc[idx, 'count'])
    }

# GPA progression
improving = (df['HSC_Result'] > df['Previous_GPA']).mean() * 100
declining = (df['HSC_Result'] < df['Previous_GPA']).mean() * 100
stable = (df['HSC_Result'] == df['Previous_GPA']).mean() * 100

# Private tuition
tuition_df = df.groupby('Private_Tuition')['HSC_Result'].agg(['mean', 'std', 'count'])
tuition_data = {}
for idx in tuition_df.index:
    tuition_data[idx] = {
        'avg_hsc': float(tuition_df.loc[idx, 'mean']),
        'std_hsc': float(tuition_df.loc[idx, 'std']),
        'count': int(tuition_df.loc[idx, 'count'])
    }

# Study hours categories
df['Study_Hours_Cat'] = pd.cut(df['Study_Hours_per_Week'], 
                                bins=[0, 10, 20, 30, 100], 
                                labels=['Low (0-10)', 'Medium (11-20)', 'High (21-30)', 'Very High (>30)'])
study_h = df.groupby('Study_Hours_Cat', observed=True)['HSC_Result'].agg(['mean', 'count'])
study_data = {}
for idx in study_h.index:
    study_data[idx] = {
        'avg_hsc': float(study_h.loc[idx, 'mean']),
        'count': int(study_h.loc[idx, 'count'])
    }

# Age distribution
age_dist = df['Age'].value_counts().sort_index().to_dict()

# Build final stats dict
import json
stats = {
    'kpis': {
        'avg_hsc': float(avg_hsc),
        'excellent_rate': float(excellent_rate),
        'at_risk_rate': float(at_risk_rate),
        'gpa_delta': float(gpa_delta),
        'attendance_corr': float(attendance_corr),
        'pass_rate': float(pass_rate)
    },
    'district_stats': district_data,
    'gender_stats': gender_data,
    'school_type_stats': school_data,
    'parent_edu_stats': edu_data,
    'internet_stats': inet_data,
    'performance_dist': perf_dist,
    'income_quartile_stats': income_data,
    'gpa_progression': {
        'improving': float(improving),
        'declining': float(declining),
        'stable': float(stable)
    },
    'tuition_stats': tuition_data,
    'study_hours_stats': study_data,
    'age_dist': {str(k): int(v) for k, v in age_dist.items()}
}

with open('/app/report_stats.json', 'w') as f:
    json.dump(stats, f, indent=2)

print("Stats saved successfully!")
print(f"Average HSC: {avg_hsc:.4f}")
print(f"District stats: {list(district_data.keys())}")
PYEOF

